/**
 * A VUE Seat Contention k6 Load Test
 * Simulates 500 Virtual Users (VUs) simultaneously attempting to hold the same 50 seats.
 * Validates:
 * 1. Zero double-holds / zero double-bookings (atomic Redis Lua holds & DB unique constraints)
 * 2. Detailed response times, conflict rates (409), and system error rates
 *
 * Usage (Run by Owner - Do NOT run unasked):
 * k6 run load-tests/seat-contention.js
 */

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

// Load authenticated session tokens generated by `npm run seed:loadtest-sessions`
// in server/scripts/loadtest-sessions.ts
let tokens = [];
try {
  tokens = JSON.parse(open('./tokens.json'));
} catch (e) {
  // Fallback if tokens.json is unpopulated or missing
  tokens = [];
}

// Custom Metrics
const acquiredHoldsCount = new Counter('acquired_holds_count');
const conflictHoldsCount = new Counter('conflict_holds_count');
const errorRate = new Rate('system_error_rate');
const holdResponseTime = new Trend('hold_response_time_ms');

export const options = {
  scenarios: {
    seat_contention_spike: {
      executor: 'per-vu-iterations',
      vus: 500, // 500 Virtual Users
      iterations: 1, // 1 simultaneous attempt per VU
      maxDuration: '30s',
    },
  },
  thresholds: {
    system_error_rate: ['rate<0.01'], // <1% system 5xx errors
    http_req_duration: ['p(95)<500'], // 95% of requests under 500ms
  },
};

const BASE_URL = __ENV.API_BASE_URL || 'http://localhost:3000';
const SHOWTIME_ID = __ENV.SHOWTIME_ID || '11111111-1111-1111-1111-111111111111';

// Generate 50 candidate seat IDs for contention
const CANDIDATE_SEAT_IDS = Array.from({ length: 50 }, (_, i) => {
  const num = String(i + 1).padStart(2, '0');
  return `00000000-0000-0000-0000-0000000000${num}`;
});

export default function () {
  const vuId = __VU;
  const token = tokens && tokens.length > 0
    ? tokens[(vuId - 1) % tokens.length]
    : `load_test_token_vu_${vuId}`;

  // Pick 1 to 3 seats from the 50 candidate seats to simulate realistic contention
  const seatIndex = (vuId - 1) % CANDIDATE_SEAT_IDS.length;
  const selectedSeatIds = [CANDIDATE_SEAT_IDS[seatIndex]];

  const url = `${BASE_URL}/showtimes/${SHOWTIME_ID}/holds`;
  const payload = JSON.stringify({
    seatIds: selectedSeatIds,
  });

  const params = {
    headers: {
      'Content-Type': 'application/json',
      // Real authenticated session token generated via server/scripts/loadtest-sessions.ts
      'Authorization': `Bearer ${token}`,
    },
  };

  const startTime = Date.now();
  const res = http.post(url, payload, params);
  holdResponseTime.add(Date.now() - startTime);

  if (res.status === 200) {
    // Successfully acquired hold
    acquiredHoldsCount.add(1);
    check(res, {
      'status is 200 (acquired)': (r) => r.status === 200,
      'hold success flag is true': (r) => JSON.parse(r.body).success === true,
    });
    errorRate.add(0);
  } else if (res.status === 409) {
    // Clean conflict: seat already held by another VU
    conflictHoldsCount.add(1);
    check(res, {
      'status is 409 (conflict)': (r) => r.status === 409,
      'conflict code is SEAT_UNAVAILABLE': (r) => {
        const body = JSON.parse(r.body);
        return body.error && body.error.code === 'SEAT_UNAVAILABLE';
      },
    });
    errorRate.add(0);
  } else if (res.status === 429) {
    // Rate limit or waiting room engaged
    check(res, {
      'status is 429': (r) => r.status === 429,
    });
    errorRate.add(0);
  } else {
    // Unexpected 5xx server failure
    errorRate.add(1);
    check(res, {
      'unexpected status': (r) => r.status < 500,
    });
  }

  sleep(1);
}

export function teardown(data) {
  console.log('--- A VUE Load Test Summary ---');
  console.log('500 VUs competed for 50 contention seats.');
  console.log('Verify in DB that acquired holds <= 50 and zero double bookings occurred.');
}

